export function Radius({
  radius = {{radius}},
  topOnly = {{topOnly}},
  background = "{{background}}",
  size = {{size}},
}) {
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 260 }}>
      <div style={{ width: size, height: size, background, boxSizing: "border-box",
        borderRadius: topOnly ? `${radius}px ${radius}px 0 0` : radius }} />
      <p style={{ marginTop: 12, fontSize: 12, color: "#241430cc" }}>border-radius: {radius}px{topOnly ? " (top corners only)" : ""}</p>
    </div>
  );
}
